@Service
public class OrderOrchestrator {
    private final OrderClient orderClient;
    private final PaymentClient paymentClient;
    private final InventoryClient inventoryClient;

    public void executeOrder(OrderRequest request) {
        String orderId = orderClient.createPendingOrder(request);
        try {
            paymentClient.processPayment(orderId, request.getPaymentDetails());
            inventoryClient.reserveStock(orderId, request.getItems());
            orderClient.completeOrder(orderId);
        } catch (PaymentFailedException | InventoryOutOfStockException e) {
            compensate(orderId);
            throw new SagaExecutionException("Saga failed, compensation triggered", e);
        }
    }

    private void compensate(String orderId) {
        inventoryClient.releaseStock(orderId);
        paymentClient.refundPayment(orderId);
        orderClient.cancelOrder(orderId);
    }
}
